・杭には工場製品を打ち込む「既製杭」と、現場で孔を掘って造る「場所打ち杭」がある。
・コンクリートの「養生」は、打ったあとに水分と温度を保って強度を育てる仕事。

━━━━━━━━━━━━━━━━━━━━━━
