━━━━━━━━━━━━━━━━━━━━━━
・沈みひび割れ・プラスチック収縮ひび割れは打込み後の初期に発生しやすい★
・タンピング（表面のたたき締め）はブリーディングが概ね終了してから行う★
・仕上げが早すぎると表面の水分・気泡を巻き込み品質低下の原因になる
・乾燥した風の強い日はプラスチック収縮ひび割れが生じやすく、
　散水・防風・日よけ等で表面の急激な乾燥を防ぐ★

