　抑止工（力で止める）
　　杭工：すべり面を貫いて打設★
　　グラウンドアンカー工：緊張力で引き止める★

・対策の基本：抑制工を先行し、必要に応じて抑止工を組み合わせる★
・緊急時に即効性が高いのは抑止工

