━━━━━━━━━━━━━━━━━━━━━━
・伸縮計・地盤傾斜計・孔内傾斜計・地下水位計を組み合わせて監視★
・移動量の急激な増加は崩壊の前兆として警戒レベルを引き上げる★
・工事中も監視を継続し、異常時は作業員を安全な場所へ退避させる★

