　水準変位｜左右レールの高さの差の狂い★｜曲線ではカントとの差で評価
　高低変位｜レール長手方向の上下の凹凸★｜列車の上下動・乗心地に影響
　通り変位｜レール長手方向の左右の曲がり★｜列車の蛇行動の原因
　平面性変位｜一定距離間の水準変位の差（ねじれ）★｜輪重減少による脱線に関与

【図解】軌道の代表的な数値
