・実行予算と実際原価の差異分析を工種別・費目別に行う★
・原価低減の余地は、施工方法の改善・機械の稼働率向上等で検討★
・出来高と原価の対比（原価管理曲線）で工事の採算状況を把握★
・原価超過の兆候が見えたら早期に対策（工法変更等）を講じる★

